-- Doctor-facing safe connection reads. This migration does not change medical-data access.
create or replace function public.get_my_doctor_connection_requests() returns table(id uuid, patient_id uuid, doctor_id uuid, status text, requested_by uuid, request_message text, requested_at timestamptz, responded_at timestamptz, created_at timestamptz, updated_at timestamptz, patient jsonb) language sql security definer set search_path = public as $$ select c.id,c.patient_id,c.doctor_id,c.status,c.requested_by,c.request_message,c.requested_at,c.responded_at,c.created_at,c.updated_at,jsonb_build_object('id',p.id,'full_name',p.full_name,'prescribe_id',p.prescribe_id) from public.doctor_patient_connections c join public.profiles p on p.id=c.patient_id where c.doctor_id=auth.uid(); $$;
grant execute on function public.get_my_doctor_connection_requests() to authenticated;
